var n=`0533-saleeg`;var t=`world-0533`;var o=`SA`;var r=`western-asia`;var a=4;var s=89;var l={en:`Saleeg`,ua:`Салег`};var d={en:`A traditional dish from Saudi Arabia, centered on chicken thigh, white rice, whole cow milk. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Саудівська Аравія. Основні складники: куряче стегно, білий рис, цільне коров'яче молоко. Домашній варіант із кількостями продуктів за етапами приготування.`};var g=[{en:`Cook the listed ingredients in simmering water for about 45 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 45 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:45,i:[[`chicken-thigh`,650,`g`],[`water`,1350,`ml`],[`ground-cardamom`,6,`g`],[`table-salt`,null,`to_taste`]]},{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 32 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 32 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:32,i:[[`white-rice`,320,`g`],[`whole-cow-milk`,680,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:9,i:[[`unsalted-butter`,70,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`ground-black-pepper`,null,`to_taste`]]}];var u={slug:n,id:t,country:`SA`,region:r,servings:4,minutes:89,title:l,text:d,steps:g};export{o as country,u as default,t as id,s as minutes,r as region,a as servings,n as slug,g as steps,d as text,l as title};